/// Shows Requirements: section when steps have requires.
#[test]
fn status_shows_requirements_section() {
    let temp = setup_project(REQUIRES_CONFIG);
    let mut s = spawn_bivvy(&["status"], temp.path());

    let text = read_to_eof(&mut s);
